(function(){let prompt=null,ua=navigator.userAgent,ios=/iPhone|iPad|iPod/.test(ua)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1,android=/Android/.test(ua),$=id=>document.getElementById(id);$('device').textContent=ios?'iPhone / iPad':android?'Android':'휴대폰에서 이 주소를 열어주세요';$('guide').textContent=ios?'Safari의 공유 버튼 → 홈 화면에 추가 → 추가를 선택하세요.':android?'Chrome 메뉴 → 앱 설치 또는 홈 화면에 추가를 선택하세요.':'Android Chrome 또는 iPhone Safari에서 설치할 수 있습니다.';window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();prompt=e});$('pwa').onclick=async()=>{if(prompt){await prompt.prompt();prompt=null}else $('guide').style.color='#ffe3a6'};fetch('/api/distribution',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(b=>{if(android&&b.android.available){$('native').hidden=false;$('native').href=b.android.url;$('native').textContent='Android APK 다운로드'}else if(ios&&b.ios.available){$('native').hidden=false;$('native').href=b.ios.url;$('native').textContent='TestFlight에서 설치'}$('status').textContent=b.pwa.available?'홈 화면 설치형 게임을 사용할 수 있습니다. 네이티브 앱 배포 여부는 기기별 버튼으로 안내합니다.':'현재는 개발 모드입니다. 공개 HTTPS 배포와 앱 설치 파일 생성이 완료되지 않았습니다.';}).catch(()=>$('status').textContent='설치 서버에 연결되지 않았습니다. 현재 페이지는 배포 준비용 파일입니다.');})();
